23	func (h *handler) createFeedHandler(w http.ResponseWriter, r *http.Request) {
24		userID := request.UserID(r)
25	
26		var feedCreationRequest model.FeedCreationRequest
27		if err := json_parser.NewDecoder(r.Body).Decode(&feedCreationRequest); err != nil {
28			response.JSONBadRequest(w, r, err)
29			return
30		}
31	
32		// Make the feed category optional for clients who don't support categories.
33		if feedCreationRequest.CategoryID == 0 {
34			category, err := h.store.FirstCategory(userID)
35			if err != nil {
36				if errors.Is(err, storage.ErrNoCategory) {
37					response.JSONBadRequest(w, r, locale.NewLocalizedError("error.feed_category_not_found").Error())
38					return
39				}
40				response.JSONServerError(w, r, err)
41				return
42			}
43			if category == nil {
44				response.JSONBadRequest(w, r, locale.NewLocalizedError("error.feed_category_not_found").Error())
45				return
46			}
47			feedCreationRequest.CategoryID = category.ID
48		}
49	
50		if validationErr := validator.ValidateFeedCreation(h.store, userID, &feedCreationRequest); validationErr != nil {
51			response.JSONBadRequest(w, r, validationErr.Error())
52			return
53		}
54	
55		feed, localizedError := feedHandler.CreateFeed(h.store, userID, &feedCreationRequest)
56		if localizedError != nil {
57			response.JSONServerError(w, r, localizedError.Error())
58			return
59		}
60	
61		response.JSONCreated(w, r, &feedCreationResponse{FeedID: feed.ID})
62	}
63	
64	func (h *handler) refreshFeedHandler(w http.ResponseWriter, r *http.Request) {
65		feedID := request.RouteInt64Param(r, "feedID")
66		if feedID == 0 {
67			response.JSONBadRequest(w, r, errors.New("invalid feed ID"))
68			return
69		}
70	
71		userID := request.UserID(r)
72		exists, err := h.store.FeedExists(userID, feedID)
73		if err != nil {
74			response.JSONServerError(w, r, err)
75			return
76		}
77		if !exists {
78			response.JSONNotFound(w, r)
79			return
80		}
81	
82		// force=true mirrors the web UI's forced refresh: it bypasses the HTTP cache
83		// and reprocesses (and re-scrapes) entries that are already stored.
84		forceRefresh := request.QueryBoolParam(r, "force", false)
85		localizedError := feedHandler.RefreshFeed(h.store, userID, feedID, forceRefresh)
86		if localizedError != nil {
87			response.JSONServerError(w, r, localizedError.Error())
88			return
89		}
90	
91		response.NoContent(w, r)
92	}
93	
94	func (h *handler) refreshAllFeedsHandler(w http.ResponseWriter, r *http.Request) {
95		userID := request.UserID(r)
96	
97		jobs, err := h.store.NewBatchBuilder().
98			WithErrorLimit(config.Opts.PollingParsingErrorLimit()).
99			WithoutDisabledFeeds().
100			WithNextCheckExpired().
101			WithUserID(userID).
102			WithLimitPerHost(config.Opts.PollingLimitPerHost()).
103			FetchJobs()
104		if err != nil {
105			response.JSONServerError(w, r, err)
106			return
107		}
108	
109		slog.Info(
110			"Triggered a manual refresh of all feeds from the API",
111			slog.Int64("user_id", userID),
112			slog.Int("nb_jobs", len(jobs)),
113		)
114	
115		go h.pool.Push(jobs)
116	
117		response.NoContent(w, r)
118	}
119	
120	func (h *handler) updateFeedHandler(w http.ResponseWriter, r *http.Request) {
121		feedID := request.RouteInt64Param(r, "feedID")
122		if feedID == 0 {
123			response.JSONBadRequest(w, r, errors.New("invalid feed ID"))
124			return
125		}
126	
127		var feedModificationRequest model.FeedModificationRequest
128		if err := json_parser.NewDecoder(r.Body).Decode(&feedModificationRequest); err != nil {
129			response.JSONBadRequest(w, r, err)
130			return
131		}
132	
133		userID := request.UserID(r)
134		originalFeed, err := h.store.FeedByID(userID, feedID)
135		if err != nil {
136			response.JSONServerError(w, r, err)
137			return
138		}
139	
140		if originalFeed == nil {
141			response.JSONNotFound(w, r)
142			return
143		}
144	
145		if validationErr := validator.ValidateFeedModification(h.store, userID, originalFeed.ID, &feedModificationRequest); validationErr != nil {
146			response.JSONBadRequest(w, r, validationErr.Error())
147			return
148		}
149	
150		feedModificationRequest.Patch(originalFeed)
151		originalFeed.ResetErrorCounter()
152		if err := h.store.UpdateFeed(originalFeed); err != nil {
153			response.JSONServerError(w, r, err)
154			return
155		}
156	
157		originalFeed, err = h.store.FeedByID(userID, feedID)
158		if err != nil {
159			response.JSONServerError(w, r, err)
160			return
161		}
162	
163		response.JSONCreated(w, r, originalFeed)
164	}
