func (s *Storage) RemoveUser(userID int64) error {
	if s.audit == nil {
		if _, err := s.db.Exec(`DELETE FROM users WHERE id=$1`, userID); err != nil {
			return fmt.Errorf(`store: unable to remove user #%d: %v`, userID, err)
		}
		return nil
	}

	tx, err := s.db.Begin()
	if err != nil {
		return fmt.Errorf(`store: unable to start transaction: %v`, err)
	}
	defer tx.Rollback()

	// Lock the user row so that no feed can be attached to it concurrently:
	// the feeds removed by the cascade must all be audited.
	if _, err := tx.Exec(`SELECT id FROM users WHERE id=$1 FOR UPDATE`, userID); err != nil {
		return fmt.Errorf(`store: unable to remove user #%d: %v`, userID, err)
	}
	if err := s.auditRows(tx, "feeds", auditActionDelete, `SELECT id FROM feeds WHERE user_id=$1`, userID); err != nil {
		return err
	}
	if err := s.auditRows(tx, "users", auditActionDelete, `SELECT id FROM users WHERE id=$1`, userID); err != nil {
		return err
	}
	if _, err := tx.Exec(`DELETE FROM users WHERE id=$1`, userID); err != nil {
		return fmt.Errorf(`store: unable to remove user #%d: %v`, userID, err)
	}
	if err := tx.Commit(); err != nil {
		return fmt.Errorf(`store: unable to commit transaction: %v`, err)
	}
	return nil
}

